solution.solution.cpp:
#include <cstdint>
#include <map>
#include <string>
#include <utility>
#include <vector>

constexpr std::uint8_t FIN{ 0x01 }, SYN{ 0x02 }, RST{ 0x04 }, PSH{ 0x08 }, ACK{ 0x10 };

struct Segment
{
    std::uint32_t sourceIp;
    std::uint16_t sourcePort;
    std::uint32_t destinationIp;
    std::uint16_t destinationPort;
    std::uint32_t sequence;
    std::uint8_t flags;
    std::string data;
};

class Tracker
{
public:
    void add(const Segment& s)
    {
        const Endpoint from{ s.sourceIp, s.sourcePort };
        const Endpoint to{ s.destinationIp, s.destinationPort };
        Direction& d{ conversations_[key(from, to)][from] };
        if ((s.flags & SYN) && !d.sawSyn) { d.sawSyn = true; d.isn = s.sequence; }
        if (s.flags & RST) d.rst = true;
        if (s.flags & FIN) d.fin = true;
        if (s.data.empty() || !d.sawSyn || (s.flags & SYN)) return;

        const std::uint32_t offset{ s.sequence - (d.isn + 1) };
        if (offset >= kLimit || s.data.size() > kLimit - offset) return;
        const std::size_t end{ offset + s.data.size() };
        if (d.have.size() < end) { d.have.resize(end, false); d.bytes.resize(end, '\0'); }
        bool fresh{ false };
        for (std::size_t i{ 0 }; i < s.data.size(); ++i)
        {
            if (d.have[offset + i]) continue;
            d.have[offset + i] = true;
            d.bytes[offset + i] = s.data[i];
            fresh = true;
        }
        if (!fresh) ++retransmissions_;
    }

    std::size_t conversations() const { return conversations_.size(); }

    std::string stream(std::uint32_t fromIp, std::uint16_t fromPort, std::uint32_t toIp, std::uint16_t toPort) const
    {
        const Endpoint from{ fromIp, fromPort };
        const auto c{ conversations_.find(key(from, { toIp, toPort })) };
        if (c == conversations_.end()) return "";
        const auto d{ c->second.find(from) };
        if (d == c->second.end()) return "";
        std::size_t length{ 0 };
        while (length < d->second.have.size() && d->second.have[length]) ++length;
        return d->second.bytes.substr(0, length);
    }

    int retransmissions() const { return retransmissions_; }

    std::string state(std::uint32_t ipA, std::uint16_t portA, std::uint32_t ipB, std::uint16_t portB) const
    {
        const auto c{ conversations_.find(key({ ipA, portA }, { ipB, portB })) };
        if (c == conversations_.end()) return "none";
        bool reset{ false };
        for (const auto& [endpoint, d] : c->second)
        {
            if (!d.rst) continue;
            if (!d.sawSyn) return "refused";
            reset = true;
        }
        if (reset) return "reset";
        int fins{ 0 };
        for (const auto& [endpoint, d] : c->second) fins += d.fin ? 1 : 0;
        return fins == 2 ? "closed" : "open";
    }

private:
    using Endpoint = std::pair<std::uint32_t, std::uint16_t>;
    struct Direction
    {
        bool sawSyn{ false };
        std::uint32_t isn{ 0 };
        bool fin{ false };
        bool rst{ false };
        std::string bytes;
        std::vector<bool> have;
    };
    static constexpr std::uint32_t kLimit{ 1u << 24 };

    static std::pair<Endpoint, Endpoint> key(Endpoint a, Endpoint b)
    {
        return a < b ? std::pair{ a, b } : std::pair{ b, a };
    }

    std::map<std::pair<Endpoint, Endpoint>, std::map<Endpoint, Direction>> conversations_;
    int retransmissions_{ 0 };
};

unitTests:
const std::uint32_t C{ 0x0A000002 }, S{ 0x0A000001 };
Segment seg(bool fromClient, std::uint32_t sequence, std::uint8_t flags, std::string data = "", std::uint16_t clientPort = 50000) {
    if (fromClient) return Segment{ C, clientPort, S, 80, sequence, flags, data };
    return Segment{ S, 80, C, clientPort, sequence, flags, data };
}
TEST("a whole conversation") {
    Tracker t;
    t.add(seg(true, 1000, SYN));
    t.add(seg(false, 5000, SYN | ACK));
    t.add(seg(true, 1001, ACK));
    t.add(seg(true, 1001, PSH | ACK, "GET / HTTP/1.1\r\n\r\n"));
    t.add(seg(false, 5001, ACK, "HTTP/1.1 200 OK\r\n"));
    t.add(seg(false, 5018, PSH | ACK, "\r\nhello"));
    CHECK_EQ(t.conversations(), 1u);
    CHECK_EQ(t.stream(C, 50000, S, 80), std::string("GET / HTTP/1.1\r\n\r\n"));
    CHECK_EQ(t.stream(S, 80, C, 50000), std::string("HTTP/1.1 200 OK\r\n\r\nhello"));
    CHECK_EQ(t.state(C, 50000, S, 80), std::string("open"));
    t.add(seg(true, 1019, FIN | ACK));
    CHECK_EQ(t.state(S, 80, C, 50000), std::string("open"));
    t.add(seg(false, 5025, FIN | ACK));
    CHECK_EQ(t.state(S, 80, C, 50000), std::string("closed"));
    CHECK_EQ(t.retransmissions(), 0);
}
TEST("out of order, across the wrap, and retransmitted") {
    Tracker t;
    t.add(seg(true, 0xFFFFFFF0, SYN));
    t.add(seg(true, 0xFFFFFFF6, ACK, " world"));
    CHECK_EQ(t.stream(C, 50000, S, 80), std::string(""));
    t.add(seg(true, 0xFFFFFFF1, ACK, "hello"));
    t.add(seg(true, 0x00000000, ACK, "end"));
    t.add(seg(true, 0xFFFFFFFE, ACK, "??"));
    CHECK_EQ(t.stream(C, 50000, S, 80), std::string("hello world"));
    t.add(seg(true, 0xFFFFFFFC, ACK, "!!"));
    CHECK_EQ(t.stream(C, 50000, S, 80), std::string("hello world!!??end"));
    CHECK_EQ(t.retransmissions(), 0);
    t.add(seg(true, 0xFFFFFFF1, ACK, "HELLO"));
    t.add(seg(true, 0xFFFFFFF4, ACK, "lo wor"));
    CHECK_EQ(t.retransmissions(), 2);
    t.add(seg(true, 0xFFFFFFFE, ACK, "??more"));
    CHECK_EQ(t.retransmissions(), 2);
    CHECK_EQ(t.stream(C, 50000, S, 80), std::string("hello world!!??ende"));
}
TEST("gaps and ignored data") {
    Tracker t;
    t.add(seg(true, 10, SYN, "in the syn"));
    t.add(seg(true, 11, ACK, "ab"));
    t.add(seg(true, 16, ACK, "xyz"));
    CHECK_EQ(t.stream(C, 50000, S, 80), std::string("ab"));
    t.add(seg(false, 900, ACK, "no syn seen"));
    CHECK_EQ(t.stream(S, 80, C, 50000), std::string(""));
    t.add(seg(true, 5, ACK, "before the start"));
    CHECK_EQ(t.stream(C, 50000, S, 80), std::string("ab"));
    CHECK_EQ(t.stream(C, 50001, S, 80), std::string(""));
}
TEST("how connections ended") {
    Tracker t;
    t.add(seg(true, 1, SYN, "", 50001));
    t.add(seg(false, 0, RST | ACK, "", 50001));
    t.add(seg(true, 100, SYN, "", 50002));
    t.add(seg(false, 700, SYN | ACK, "", 50002));
    t.add(seg(true, 101, ACK, "data", 50002));
    t.add(seg(false, 701, RST, "", 50002));
    t.add(seg(true, 300, SYN, "", 50003));
    CHECK_EQ(t.conversations(), 3u);
    CHECK_EQ(t.state(C, 50001, S, 80), std::string("refused"));
    CHECK_EQ(t.state(S, 80, C, 50001), std::string("refused"));
    CHECK_EQ(t.state(C, 50002, S, 80), std::string("reset"));
    CHECK_EQ(t.state(C, 50003, S, 80), std::string("open"));
    CHECK_EQ(t.state(C, 50004, S, 80), std::string("none"));
}

